import React, { useState, useEffect } from "react";
import "./styles/main.css";

function App() {
  const [dark, setDark] = useState(false);

  useEffect(() => {
    if (dark) {
      document.body.classList.add("dark");
    } else {
      document.body.classList.remove("dark");
    }
  }, [dark]);

  const openWindow = (page) => {
    window.open(
      `/${page}.html`,
      "_blank",
      "width=1400,height=760"
    );
  };

  return (
    <div className="home">

      {/* Правый верхний угол */}
      <div className="top-menu">
        <button onClick={() => openWindow("projects")}>Projects</button>
        <button onClick={() => openWindow("skills")}>Skills</button>
        <button onClick={() => openWindow("contacts")}>Contacts</button>

        <button
          className="theme-btn"
          onClick={() => setDark(!dark)}
        >
          {dark ? "☀" : "🌙"}
        </button>
      </div>

      {/* Главный экран */}
      <div className="main-content">
        <h1>Hi, my name is <strong>John Doe</strong></h1>
        <h2>a frontend developer</h2>
        <h3>with passion for learning and creating.</h3>

        <img
          src="/img/header-bg.png"
          alt="Profile"
          className="profile-img"
        />
      </div>

    </div>
  );
}

export default App;
